import { describe, it, expect } from "vitest";

import * as utf_32be from "./utf-32be.js";

describe("UTF-32 (big-endian)", () => {
  describe("encode", () => {
    it("correctly encodes sample inputs", () => {
      // python3 -c 'print("يولد جميع البشر أحرارًا ومتساوون في الكرامة والحقوق، وقد وهبوا عقلاً وضميرًا وعليهم أن يعاملوا بعضهم بعض بروح الإخاء." .encode("utf-32be").hex())'
      expect(
        utf_32be.encode(
          "يولد جميع البشر أحرارًا ومتساوون في الكرامة والحقوق، وقد وهبوا عقلاً وضميرًا وعليهم أن يعاملوا بعضهم بعض بروح الإخاء.",
        ),
      ).toEqual(
        Uint8Array.fromHex(
          "",
        ),
      );
    });
  });

  describe("survives roundtrip conversion", () => {
    it("sample input", () => {
      const input =
        "يولد جميع البشر أحرارًا ومتساوون في الكرامة والحقوق، وقد وهبوا عقلاً وضميرًا وعليهم أن يعاملوا بعضهم بعض بروح الإخاء.";

      expect(utf_32be.decode(utf_32be.encode(input))).toEqual(input);
      expect(
        utf_32be.decode(utf_32be.encode(input, { addBOM: true }), {
          stripBOM: true,
        }),
      ).toEqual(input);
    });
  });
});
